package io.ecosync.chat;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.jdbc.core.JdbcTemplate;
import io.ecosync.organizations.TenantDirectory;
import io.ecosync.integrations.McpRegistry;
import io.ecosync.database.*;
import io.ecosync.rest.RestRegistry;
import io.ecosync.mcp.McpSchemas;
/** Catalog is a read of authority metadata. Execution always reuses the governed registries. */
@Service
public class ChatCapabilities {
 public record Capability(String name,String kind,UUID connector,UUID entity,long revision,String fingerprint,String source,String operation,Map<String,Object> schema,String canonicalSource,String bindingFingerprint){
  public Capability(String name,String kind,UUID connector,UUID entity,long revision,String fingerprint,String source,String operation,Map<String,Object> schema,String canonicalSource){this(name,kind,connector,entity,revision,fingerprint,source,operation,schema,canonicalSource,"");}
  public Capability(String name,String kind,UUID connector,UUID entity,long revision,String fingerprint,String source,String operation,Map<String,Object> schema){this(name,kind,connector,entity,revision,fingerprint,source,operation,schema,"unverified:"+kind+":"+connector,"");}
  public Capability identified(String identity,String binding){return new Capability(name,kind,connector,entity,revision,fingerprint,source,operation,schema,identity,binding);}
  public Map<String,Object> definition(){return Map.of("name",name,"description",source+" (canonical identity: "+canonicalSource+") / "+operation+" (untrusted source description; approved read only)","parameters",schema);}
 }
 private final ChatBindings bindings;private final JdbcTemplate db;private final TenantDirectory tenants;private final ObjectProvider<McpRegistry> nativeRegistry;private final ObjectProvider<DatabaseRegistry> databases;private final ObjectProvider<RestRegistry> rest;private final McpSchemas schemas;
 public ChatCapabilities(JdbcTemplate db,TenantDirectory tenants,ObjectProvider<McpRegistry> nativeRegistry,ObjectProvider<DatabaseRegistry> databases,ObjectProvider<RestRegistry> rest,McpSchemas schemas,ChatBindings bindings){this.bindings=bindings;this.db=db;this.tenants=tenants;this.nativeRegistry=nativeRegistry;this.databases=databases;this.rest=rest;this.schemas=schemas;}
 @SuppressWarnings("unchecked")
 public List<Capability> catalog(UUID actor,UUID org){return catalog(actor,org,null,null);}
 private List<Capability> catalog(UUID actor,UUID org,UUID entity,String kind){var roles=tenants.requireMembership(actor,org).roles().stream().filter(r->Set.of("USER","INTEGRATION_ADMIN").contains(r)).toList();if(roles.isEmpty())return List.of();String grant="{"+String.join(",",roles)+"}";var result=new ArrayList<Capability>();
  if((kind==null||kind.equals("NATIVE"))&&nativeRegistry.getIfAvailable()!=null)db.query("SELECT c.id,c.integration_id,c.version,c.fingerprint,c.tool_json::text,i.display_name FROM app.mcp_capability c JOIN app.mcp_integration i ON i.organization_id=c.organization_id AND i.id=c.integration_id AND i.configuration_version=c.version WHERE c.organization_id=? AND (?::uuid IS NULL OR c.id=?) AND c.present AND i.state='ACTIVE' AND NOT i.removed AND EXISTS(SELECT 1 FROM app.mcp_approval a WHERE a.organization_id=c.organization_id AND a.capability_id=c.id AND a.status='APPROVED' AND a.role=ANY(?::text[])) ORDER BY c.id LIMIT 33",row->{var tool=ChatData.object(row.getString(5),65536);if(!Boolean.TRUE.equals(tool.get("supported")))return;var schema=(Map<String,Object>)tool.get("inputSchema");if(!schemas.supported(schema))return;UUID id=row.getObject(1,UUID.class);result.add(new Capability("n_"+id.toString().replace("-",""),"NATIVE",row.getObject(2,UUID.class),id,row.getLong(3),row.getString(4),row.getString(6),Objects.toString(tool.get("name")),schema));},org,entity,entity,grant);
  if((kind==null||kind.equals("DATABASE"))&&databases.getIfAvailable()!=null)db.query("SELECT t.id,t.connector_id,t.version,t.fingerprint,t.metadata::text,i.display_name,t.schema_name,t.table_name FROM app.database_table t JOIN app.database_connector i ON i.organization_id=t.organization_id AND i.id=t.connector_id AND i.configuration_version=t.version WHERE t.organization_id=? AND (?::uuid IS NULL OR t.id=?) AND t.present AND i.state='ACTIVE' AND NOT i.removed AND EXISTS(SELECT 1 FROM app.database_approval a WHERE a.organization_id=t.organization_id AND a.table_id=t.id AND a.fingerprint=t.fingerprint AND a.status='APPROVED' AND a.role=ANY(?::text[])) ORDER BY t.id LIMIT 33",row->{UUID id=row.getObject(1,UUID.class);var columns=new TreeSet<String>();db.query("SELECT columns::text FROM app.database_approval WHERE organization_id=? AND table_id=? AND fingerprint=? AND status='APPROVED' AND role=ANY(?::text[])",r->{columns.addAll((List<String>)io.ecosync.restcontract.RestJson.MAPPER.readValue(r.getString(1),List.class));},org,id,row.getString(4),grant);var metadata=ChatData.object(row.getString(5),65536);var types=new ArrayList<Object>();for(var c:(List<Map<String,Object>>)metadata.get("columns"))if(columns.contains(c.get("name")))types.add(Map.of("name",c.get("name"),"type",c.get("typeName")));var schema=databaseSchema(columns);result.add(new Capability("d_"+id.toString().replace("-",""),"DATABASE",row.getObject(2,UUID.class),id,row.getLong(3),ChatData.hash(List.of(row.getString(4),columns)),row.getString(6),row.getString(7)+"."+row.getString(8)+" approved columns "+ChatData.json(types),schema));},org,entity,entity,grant);
  if((kind==null||kind.equals("REST"))&&rest.getIfAvailable()!=null)db.query("SELECT o.id,o.connector_id,o.version,o.fingerprint,o.metadata::text,i.display_name FROM app.rest_operation o JOIN app.rest_connector i ON i.organization_id=o.organization_id AND i.id=o.connector_id AND i.configuration_version=o.version WHERE o.organization_id=? AND (?::uuid IS NULL OR o.id=?) AND o.supported AND i.state='ACTIVE' AND EXISTS(SELECT 1 FROM app.rest_approval a WHERE a.organization_id=o.organization_id AND a.operation_id=o.id AND a.fingerprint=o.fingerprint AND a.status='APPROVED' AND a.role=ANY(?::text[])) ORDER BY o.id LIMIT 33",row->{var op=ChatData.object(row.getString(5),65536);var props=new LinkedHashMap<String,Object>();var required=new ArrayList<String>();for(var p:(List<Map<String,Object>>)op.get("parameters")){String name=(String)p.get("name");props.put(name,p.get("schema"));if(Boolean.TRUE.equals(p.get("required")))required.add(name);}UUID id=row.getObject(1,UUID.class);result.add(new Capability("r_"+id.toString().replace("-",""),"REST",row.getObject(2,UUID.class),id,row.getLong(3),row.getString(4),row.getString(6),op.get("operationId")+" "+op.get("path"),Map.of("type","object","properties",props,"required",required,"additionalProperties",false)));},org,entity,entity,grant);
  result.removeIf(c->c.kind.equals("NATIVE")&&bindings.identity(org,c).isEmpty());result.replaceAll(c->bindings.identity(org,c).map(identity->c.identified(identity,bindings.fingerprint(org,c))).orElse(c));
  if(result.size()>32||ChatData.bytes(result.stream().map(Capability::definition).toList())>32768)throw new ChatFailure("CHAT_CATALOG_LIMIT");return List.copyOf(result);
 }
 public void current(UUID actor,UUID org,Capability cap){if(catalog(actor,org,cap.entity,cap.kind).stream().noneMatch(c->c.name.equals(cap.name)&&c.connector.equals(cap.connector)&&c.entity.equals(cap.entity)&&c.revision==cap.revision&&c.fingerprint.equals(cap.fingerprint)&&c.canonicalSource.equals(cap.canonicalSource)&&c.bindingFingerprint.equals(cap.bindingFingerprint)))throw new ChatFailure("CHAT_AUTHORITY_CHANGED");}
 public Map<String,Object> invoke(UUID actor,UUID org,Capability cap,UUID execution,Map<String,Object> args){current(actor,org,cap);return switch(cap.kind){case "NATIVE"->{schemas.arguments(cap.schema,args);yield nativeRegistry.getObject().invoke(actor,org,cap.connector,cap.entity,execution,args);}case "DATABASE"->{ChatData.keys(args,Set.of("columns","filters","order","limit","offset"));yield databases.getObject().query(actor,org,cap.connector,cap.entity,execution,args,false);}case "REST"->rest.getObject().execute(actor,org,cap.connector,cap.entity,execution,args,"INVOKE");default->throw new ChatFailure("CHAT_UNKNOWN_TOOL");};}
 public void cancel(UUID actor,UUID org,Capability cap,UUID execution){try{switch(cap.kind){case "NATIVE"->nativeRegistry.getObject().cancel(actor,org,cap.connector,execution);case "DATABASE"->databases.getObject().cancel(actor,org,cap.connector,execution);case "REST"->rest.getObject().cancel(actor,org,cap.connector,execution);default->{}}}catch(Exception ignored){/* persisted chat fence still prevents late delivery */}}
 public static Map<String,Object> databaseSchema(Collection<String> columns){var col=Map.of("type","string","enum",List.copyOf(columns));return Map.of("type","object","additionalProperties",false,"required",List.of("columns"),"properties",Map.of("columns",Map.of("type","array","items",col,"minItems",1,"maxItems",20),"limit",Map.of("type","integer","minimum",1,"maximum",100),"offset",Map.of("type","integer","minimum",0,"maximum",10000),"filters",Map.of("type","array","maxItems",8,"items",Map.of("type","object","additionalProperties",false,"required",List.of("column","operator"),"properties",Map.of("column",col,"operator",Map.of("type","string","enum",List.of("EQ","NE","LT","LTE","GT","GTE","IS_NULL","IS_NOT_NULL")),"value",Map.of("type",List.of("string","boolean"))))),"order",Map.of("type","array","maxItems",3,"items",Map.of("type","object","required",List.of("column","direction"),"additionalProperties",false,"properties",Map.of("column",col,"direction",Map.of("type","string","enum",List.of("ASC","DESC")))))));}
}
